<script setup lang="ts">
import { computed, ref, watch } from "vue";
import { useRoute, useRouter, onBeforeRouteUpdate } from "vue-router";
import { MEMORY_CATEGORIES, ROLE_NAMES, isLlmAgentId, parseParkTimestamp, shanghaiDateTime, shanghaiTimestamp, type AgentDetail, type AgentMemory, type MemoryCategory, type MemoryOverview, type MemorySettings, type AgentModelSettings } from "@vectra/shared";
import { api } from "../api";
import { actorFor } from "../conversation";
import { useWorkspace } from "../stores/workspace";
import { useUnsavedChanges } from "../use-unsaved-changes";
import ActorAvatar from "../components/ActorAvatar.vue";
import AgentModelPanel from "../components/AgentModelPanel.vue";
const route = useRoute(), router = useRouter(), workspace = useWorkspace(), detail = ref<AgentDetail>(), memories = ref<MemoryOverview>(), busy = ref(false), saving = ref(false), message = ref(""), failed = ref(false), tab = ref("capabilities"), query = ref(""), category = ref(""), state = ref(""), page = ref(1), draft = ref<ReturnType<typeof blank>>(), settingsDraft = ref<MemorySettings>();
const id = computed(() => typeof route.params.id === "string" && isLlmAgentId(route.params.id) ? route.params.id : undefined);
function blank(item?: AgentMemory) { return { id: item?.id, revision: item?.revision, title: item?.title ?? "", content: item?.content ?? "", category: item?.category ?? "preference" as MemoryCategory, tags: item?.tags.join("、") ?? "", enabled: item?.enabled ?? true, pinned: item?.pinned ?? false, expiresAt: item?.expiresAt ? shanghaiTimestamp(item.expiresAt).slice(0, 16) : "" }; }
const confirmDiscard = useUnsavedChanges(() => !!draft.value, "长期记忆编辑");
onBeforeRouteUpdate(to => to.params.id === route.params.id || confirmDiscard());
const filtered = computed(() => (memories.value?.items ?? []).filter(item => (!category.value || item.category === category.value) && (!state.value || (state.value === "active" ? item.enabled && (!item.expiresAt || item.expiresAt > Date.now()) : state.value === "expired" ? !!item.expiresAt && item.expiresAt <= Date.now() : !item.enabled))));
const pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / 10))), shown = computed(() => filtered.value.slice((Math.min(page.value, pages.value) - 1) * 10, Math.min(page.value, pages.value) * 10));
const sourceLabel = (item: AgentMemory) => item.source === "manual" ? "手工维护" : item.source === "user_request" ? "用户在对话中要求记住" : "已完成任务的批准结果";
function fail(cause: unknown) { failed.value = true; message.value = cause instanceof Error ? cause.message : String(cause); }
async function loadMemory() { if (id.value !== "coordinator") return; memories.value = await api<MemoryOverview>("/api/agents/coordinator/memories?q=" + encodeURIComponent(query.value)); settingsDraft.value = { ...memories.value.settings }; page.value = 1; }
async function load() { if (!id.value) { detail.value = undefined; message.value = "未找到该 Agent。"; return; } busy.value = true; failed.value = false; message.value = ""; const selected = id.value; try { const value = await api<AgentDetail>("/api/agents/" + selected); if (selected !== id.value) return; detail.value = value; if (selected === "coordinator") await loadMemory(); else memories.value = undefined; } catch (cause) { fail(cause); } finally { busy.value = false; } }
async function search() { busy.value = true; try { await loadMemory(); } catch (cause) { fail(cause); } finally { busy.value = false; } }
function edit(item?: AgentMemory) { if (!confirmDiscard()) return; draft.value = blank(item); message.value = ""; }
function cancel() { if (confirmDiscard()) draft.value = undefined; }
async function saveMemory() { if (!draft.value) return; saving.value = true; message.value = ""; failed.value = false; try { const { id: memoryId, tags, expiresAt, ...value } = draft.value, at = expiresAt ? parseParkTimestamp(expiresAt) : undefined; if (expiresAt && !Number.isFinite(at)) throw new Error("请输入有效的上海时间有效期。"); await api("/api/agents/coordinator/memories" + (memoryId ? "/" + memoryId : ""), { method: memoryId ? "PUT" : "POST", body: JSON.stringify({ ...value, tags: tags.split(/[、,，]/).map(tag => tag.trim()).filter(Boolean), expiresAt: at ?? null }) }); draft.value = undefined; await loadMemory(); message.value = "记忆已保存。后续新任务会按相关性、启用状态和有效期检索。"; } catch (cause) { fail(cause); } finally { saving.value = false; } }
async function toggle(item: AgentMemory) { saving.value = true; failed.value = false; try { await api("/api/agents/coordinator/memories/" + item.id, { method: "PUT", body: JSON.stringify({ title: item.title, content: item.content, category: item.category, tags: item.tags, enabled: !item.enabled, pinned: item.pinned, expiresAt: item.expiresAt ?? null, revision: item.revision }) }); await loadMemory(); } catch (cause) { fail(cause); } finally { saving.value = false; } }
async function remove(item: AgentMemory) { if (!window.confirm("删除记忆“" + item.title + "”？删除后不会再被后续任务检索。")) return; saving.value = true; failed.value = false; try { await api("/api/agents/coordinator/memories/" + item.id, { method: "DELETE", body: JSON.stringify({ revision: item.revision }) }); if (draft.value?.id === item.id) draft.value = undefined; await loadMemory(); message.value = "记忆已删除。"; } catch (cause) { fail(cause); } finally { saving.value = false; } }
async function saveSettings() { if (!settingsDraft.value) return; saving.value = true; try { const value = await api<MemorySettings>("/api/agents/coordinator/memory-settings", { method: "PUT", body: JSON.stringify(settingsDraft.value) }); if (memories.value) memories.value.settings = value; failed.value = false; message.value = "长期记忆设置已保存。"; } catch (cause) { fail(cause); } finally { saving.value = false; } }
function modelSaved(value: AgentModelSettings) { if (detail.value) detail.value.model = value; if (value.agentId === "coordinator") workspace.modelSettings = value; }
const sourceMissing = (item: AgentMemory) => !!item.sourceConversationId && !!workspace.overview && !workspace.conversations.some(conversation => conversation.id === item.sourceConversationId);
async function openSource(item: AgentMemory) { if (sourceMissing(item)) { message.value = "来源对话已删除，记忆完整保留，可在此独立管理。"; return; } if (!item.sourceConversationId || !confirmDiscard()) return; draft.value = undefined; await workspace.select(item.sourceConversationId); await router.push("/"); }
watch(id, () => { detail.value = undefined; draft.value = undefined; tab.value = route.query.section === "model" ? "model" : "capabilities"; query.value = ""; void load(); }, { immediate: true });
watch(() => route.query.section, value => { if (value === "model") tab.value = "model"; });
</script>
<template>
  <section class="agent-page"><RouterLink class="agent-back" to="/agents">← Agent 工作组</RouterLink><div v-if="detail" class="agent-heading"><div class="agent-detail-title"><ActorAvatar :actor="actorFor(detail.identity.id)" /><div><span class="agent-eyebrow">{{ detail.definition.parentId ? '子智能体 · 接受主智能体委派' : '主智能体 · 统一记忆与任务委派' }}</span><h1>{{ detail.identity.displayName }}</h1><p>{{ detail.definition.summary }}</p></div></div><UiButton class="secondary" :disabled="busy || saving || !!draft" @click="load">刷新详情</UiButton></div><UiAlert v-if="message" class="agent-feedback" :class="{ error: failed }" role="status">{{ message }}</UiAlert>
    <template v-if="detail && id"><div class="agent-detail-facts"><span>登记编号 <b>{{ id }}</b></span><span>底层模型 <b>{{ detail.model.model || '待配置' }}</b></span><span>{{ detail.model.ready ? '独立模型配置' : '待配置底层模型' }}</span><span>{{ detail.definition.hasLongTermMemory ? '拥有长期记忆' : '仅本次任务上下文' }}</span></div>
      <div class="agent-tabs" role="tablist" aria-label="Agent 详情分类"><UiButton v-for="item in [{ id: 'capabilities', label: '职责与工具' }, { id: 'model', label: '底层模型' }, { id: 'memory', label: '长期记忆' }, { id: 'runs', label: '执行记录' }]" :key="item.id" role="tab" :aria-selected="tab === item.id" :class="{ active: tab === item.id }" @click="tab = item.id">{{ item.label }}</UiButton></div>
      <section v-if="tab === 'capabilities'" class="agent-panel"><div class="agent-duty-columns"><div><h2>负责什么</h2><ul><li v-for="goal in detail.definition.goals" :key="goal">{{ goal }}</li></ul></div><div><h2>权限边界</h2><ul><li v-for="boundary in detail.definition.boundaries" :key="boundary">{{ boundary }}</li></ul></div></div><h2>可调用工具 · {{ detail.tools.length }} 项</h2><p class="agent-copy">以下是登记能力；每轮会根据任务类型进一步限制可用工具。</p><div class="agent-tool-grid"><article v-for="tool in detail.tools" :key="tool.name" class="agent-tool"><span class="agent-pill">{{ tool.access }}</span><h3>{{ tool.label }}</h3><p>{{ tool.purpose }}</p><small>适用：{{ tool.intents.map(intent => ({ statistics: '统计', investigation: '调查', verification: '验签', explain: '说明' })[intent]).join('、') }}</small><details><summary>工具标识</summary><code>{{ tool.name }}</code></details></article></div></section>
      <section v-show="tab === 'model'" class="agent-panel"><AgentModelPanel :key="id" :agent-id="id" @saved="modelSaved" /></section>
      <section v-if="tab === 'memory' && id !== 'coordinator'" class="agent-panel agent-empty"><h2>此子智能体不持有长期记忆</h2><p>长期记忆由主智能体统一管理。{{ detail.identity.displayName }}仅接收本次委派提供的相关背景、批准方案或证据，任务结束后不会建立自己的跨对话记忆。</p><RouterLink to="/agents/coordinator">查看{{ ROLE_NAMES.coordinator }}的长期记忆 ↗</RouterLink></section>
      <template v-if="tab === 'memory' && id === 'coordinator' && memories && settingsDraft"><section class="agent-panel"><h2>长期记忆的使用方式</h2><div class="agent-memory-options"><label><input v-model="settingsDraft.enabled" type="checkbox" />启用长期记忆检索</label><label><input v-model="settingsDraft.autoCapture" type="checkbox" />保存已完成统计任务的批准结果作为历史经验</label><label>每轮最多引用 <UiSelect v-model.number="settingsDraft.maxRecall"><option v-for="n in 8" :key="n" :value="n">{{ n }} 条</option></UiSelect></label><UiButton class="secondary" :disabled="saving" @click="saveSettings">保存记忆设置</UiButton></div><p class="agent-copy">偏好可手工添加，也可以在对话中明确说“请记住……”。历史任务记忆默认30天有效，且始终标注日期与来源。停用或过期的内容不会进入新任务；记忆不能覆盖你本轮明确要求或批准规则。</p></section>
        <section class="agent-panel"><div class="agent-section-heading"><h2>记忆库 · 共 {{ memories.total }} 条</h2><UiButton class="primary" :disabled="saving" @click="edit()">新增记忆</UiButton></div><form class="agent-memory-search" @submit.prevent="search"><UiInput v-model="query" maxlength="200" placeholder="搜索标题、内容或标签" aria-label="检索长期记忆" /><UiSelect v-model="category" @change="page = 1"><option value="">全部分类</option><option v-for="(label, value) in MEMORY_CATEGORIES" :key="value" :value="value">{{ label }}</option></UiSelect><UiSelect v-model="state" @change="page = 1"><option value="">全部状态</option><option value="active">可被引用</option><option value="paused">已停用</option><option value="expired">已过期</option></UiSelect><UiButton :disabled="busy">查找</UiButton></form>
          <form v-if="draft" class="agent-memory-editor" @submit.prevent="saveMemory"><h3>{{ draft.id ? '修改记忆' : '新增记忆' }}</h3><label>标题<UiInput v-model="draft.title" maxlength="80" required /></label><div class="agent-memory-fields"><label>分类<UiSelect v-model="draft.category"><option v-for="(label, value) in MEMORY_CATEGORIES" :key="value" :value="value">{{ label }}</option></UiSelect></label><label>有效期（上海，可留空）<UiInput v-model="draft.expiresAt" type="datetime-local" /></label></div><label>内容<UiInput type="textarea" v-model="draft.content" rows="5" maxlength="2000" required placeholder="例如：园区运行分析默认关注东入口；优先展示排队时长和车次数。" /></label><label>标签（用顿号或逗号分隔）<UiInput v-model="draft.tags" placeholder="东入口、排队、运营偏好" /></label><div class="agent-memory-options"><label><input v-model="draft.enabled" type="checkbox" />允许后续任务引用</label><label><input v-model="draft.pinned" type="checkbox" />置顶</label></div><div class="button-row"><UiButton class="primary" :disabled="saving">{{ saving ? '保存中…' : '保存记忆' }}</UiButton><UiButton type="button" class="secondary" :disabled="saving" @click="cancel">取消</UiButton></div></form>
          <div class="agent-memory-list"><article v-for="item in shown" :key="item.id" class="agent-memory-item"><div class="agent-section-heading"><div><span class="agent-pill">{{ MEMORY_CATEGORIES[item.category] }}</span><span v-if="item.pinned" class="agent-memory-status">置顶</span><span class="agent-memory-status">{{ !item.enabled ? '已停用' : item.expiresAt && item.expiresAt <= Date.now() ? '已过期' : '可被引用' }}</span><h3>{{ item.title }}</h3></div><div class="button-row"><UiButton :disabled="saving" @click="edit(item)">修改</UiButton><UiButton :disabled="saving" @click="toggle(item)">{{ item.enabled ? '停用' : '启用' }}</UiButton><UiButton class="agent-delete" :disabled="saving" @click="remove(item)">删除</UiButton></div></div><p class="agent-memory-content">{{ item.content }}</p><div class="agent-memory-tags"><span v-for="tag in item.tags" :key="tag">{{ tag }}</span></div><p class="agent-copy">{{ sourceLabel(item) }} · {{ shanghaiDateTime(item.updatedAt) }} 更新 · 已引用 {{ item.usedCount }} 次<span v-if="item.expiresAt"> · {{ shanghaiDateTime(item.expiresAt) }} 到期</span></p><RouterLink v-if="item.sourceConversationId && !sourceMissing(item)" to="/" @click.prevent="openSource(item)">查看来源对话 ↗</RouterLink><p v-else-if="sourceMissing(item)" class="agent-copy">来源对话已删除，记忆完整保留，可在此独立管理。</p></article><p v-if="!shown.length" class="agent-empty">{{ memories.total ? '没有符合筛选条件的记忆。' : '尚无长期记忆。可以手工添加，或在对话中明确要求主智能体记住。' }}</p></div><div class="agent-pagination"><UiButton :disabled="page <= 1" @click="page--">上一页</UiButton><span>{{ Math.min(page, pages) }} / {{ pages }} · {{ filtered.length }} 条</span><UiButton :disabled="page >= pages" @click="page++">下一页</UiButton></div>
        </section></template>
      <section v-if="tab === 'runs'" class="agent-panel"><div class="agent-summary"><div><small>累计执行</small><strong>{{ detail.stats.total }}</strong></div><div><small>已完成</small><strong>{{ detail.stats.completed }}</strong></div><div><small>进行中</small><strong>{{ detail.stats.running }}</strong></div><div><small>未完成</small><strong>{{ detail.stats.failed }}</strong></div></div><h2>最近30次执行</h2><p class="agent-copy">这里记录 Agent 负责的执行段及真实模型、时间和委派关系；切换模型不会改写历史。整轮是否交付，以对话最终状态和报告为准。</p><div v-for="run in detail.runs" :key="run.id" class="agent-run"><div><strong>{{ run.purpose }}</strong><span class="agent-pill">{{ ({ running: '执行中', completed: '已完成', failed: '未完成', cancelled: '已取消', queued: '排队中' })[run.status] }}</span></div><p>{{ run.parentAgentId ? '由' + ROLE_NAMES[run.parentAgentId] + '委派' : '主智能体协调执行' }} · {{ run.model }}</p><p>开始 {{ shanghaiDateTime(run.startedAt) }}<span v-if="run.finishedAt"> · 完成 {{ shanghaiDateTime(run.finishedAt) }}</span><span v-if="run.errorCode"> · 错误代码 {{ run.errorCode }}</span></p><details><summary>任务与产物标识</summary><p>执行编号 {{ run.id }}<br />任务编号 {{ run.taskId }}<br />产物摘要 {{ run.resultDigest || '尚未交付' }}</p></details></div><p v-if="!detail.runs.length" class="agent-empty">尚无执行记录。发起对应任务后，这里会展示实际调用情况。</p></section>
    </template><p v-else-if="busy" class="agent-empty">正在读取 Agent 详情…</p>
  </section>
</template>
